import {MATERIALS,WINDOWS,POINTS,DEPOT,CAPACITY,plan,metrics,seed,validateBooking,recordOutcome,csv} from './core.js';
const KEY='reloop-demo-v1';let storageWarning=false;let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.version!==1||!Array.isArray(state.requests)||!Array.isArray(state.rounds))state=seed();}catch{state=seed();storageWarning=true;}
let selectedWindow='all',collectionFilter='all',routeMode='optimised';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Number(n).toFixed(1),pct=n=>n===null?'—':Math.round(n)+'%';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageWarning=true;toast('Storage is unavailable. This session is temporary.');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3800);}
const material=r=>`<div class="material-cell"><span class="material-icon">${MATERIALS[r.material].icon}</span><div>${MATERIALS[r.material].name}<small>${esc(r.source)}</small></div></div>`;
const status=r=>`<span class="badge ${r.status==='pending'?'amber':r.status==='rejected'?'red':r.status==='missed'?'gray':''}">${({pending:'Awaiting round',scheduled:'Scheduled',collected:'Collected',rejected:'Rejected',missed:'Missed'})[r.status]}</span>`;
const heading=(title,sub,action='',eyebrow='COLLECT BETTER. TOGETHER.')=>`<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`;
const stat=(label,value,unit,foot,icon)=>`<div class="stat"><div class="stat-top"><span>${label}</span><span>${icon}</span></div><div class="stat-value">${value} <small>${unit}</small></div><div class="stat-foot">${foot}</div></div>`;
function stats(){const m=metrics(state.requests);return `<div class="stats">${stat('Accepted material',num(m.accepted),'kg','Collector-recorded demo weight','♧')}${stat('Completion rate',pct(m.completion),'',`${m.collected} collected / ${m.closed} closed pickups`,'✓')}${stat('Material rejection',pct(m.rejection),'',`${num(m.rejected)} kg rejected / inspected kg`,'⊘')}${stat('Awaiting a round',state.requests.filter(r=>r.status==='pending').length,'pickups','Ready to group by collection window','⌁')}</div>`;}
function activePlans(){return plan(state.requests).filter(g=>selectedWindow==='all'||g.window===selectedWindow);}
function totals(groups){return {baseline:groups.reduce((s,g)=>s+g.baseline,0),km:groups.reduce((s,g)=>s+g.km,0),kg:groups.reduce((s,g)=>s+g.estimated,0),count:groups.reduce((s,g)=>s+g.stops.length,0)};}
function map(groups,mode='optimised'){const xy=p=>[50+p.x*110,285-p.y*52];const line=(a,b)=>{const[x,y]=xy(a),[xx,yy]=xy(b);return `${x},${y} ${xx},${y} ${xx},${yy}`;};const routeLines=groups.map(g=>{let ps=mode==='ungrouped'?g.stops.flatMap(r=>[DEPOT,POINTS.find(p=>p.id===r.pointId),DEPOT]):[DEPOT,...g.stops.map(r=>POINTS.find(p=>p.id===r.pointId)),DEPOT];return ps.slice(1).map((p,i)=>`<polyline points="${line(ps[i],p)}" fill="none" stroke="${mode==='ungrouped'?'#a5ad91':'#36745a'}" stroke-width="${mode==='ungrouped'?2:3}" stroke-linejoin="round" opacity=".65" ${mode==='ungrouped'?'stroke-dasharray="5 5"':''}/>`).join('');}).join('');const used=[...new Set(groups.flatMap(g=>g.stops.map(r=>r.pointId)))];return `<div class="map"><svg viewBox="0 0 610 330" role="img" aria-label="Schematic Meranti neighbourhood map with ${used.length} collection points. ${mode} routes shown; not a road navigation map."><defs><pattern id="blocks" width="75" height="56" patternUnits="userSpaceOnUse"><rect x="6" y="6" width="59" height="40" rx="5" fill="#e2e7d8" stroke="#d9dfd0" stroke-width="1"/></pattern></defs><rect width="610" height="330" fill="#f1f3e9"/><rect width="610" height="330" fill="url(#blocks)"/><path d="M390 -10C315 100 470 150 410 340" stroke="#d0e0d9" stroke-width="35" fill="none"/><path d="M0 240H610M140 0V330M300 0V330M0 105H610" stroke="#fffef7" stroke-width="14"/><rect x="174" y="125" width="95" height="73" rx="24" fill="#ceddbb"/><g fill="#b8cfa3"><circle cx="188" cy="140" r="10"/><circle cx="249" cy="181" r="9"/><circle cx="218" cy="161" r="13"/></g><text x="190" y="219" class="map-label">MERANTI PARK</text><text x="460" y="35" class="map-label" style="letter-spacing:2px">MERANTI</text><text x="535" y="65" class="map-label">N ↑</text>${routeLines}${used.map((id,i)=>{const p=POINTS.find(p=>p.id===id);const[x,y]=xy(p);return `<g><title>${esc(p.name)}</title><circle cx="${x}" cy="${y}" r="13" fill="#fff" stroke="#3a7054" stroke-width="2"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="10" fill="#2b6044" font-weight="700">${i+1}</text></g>`;}).join('')}<rect x="${xy(DEPOT)[0]-15}" y="${xy(DEPOT)[1]-15}" width="30" height="30" rx="6" fill="#174f3d"/><text x="${xy(DEPOT)[0]}" y="${xy(DEPOT)[1]+5}" fill="#fff" text-anchor="middle" font-size="16">⌂</text><text x="28" y="312" class="map-label">COLLECTOR HUB</text></svg></div><div class="map-caption"><span>● ${used.length} collection points · ${groups.length} rounds</span><span>Synthetic grid · schematic distances</span></div>`;}
function comparison(groups){const t=totals(groups);const saving=t.baseline?Math.round((1-t.km/t.baseline)*100):0;return `<div class="insight"><div class="compare-row"><div><span>Individual pickups</span><strong>${num(t.baseline)} <small>km</small></strong></div><div class="bar"><span style="width:${t.count?100:0}%"></span></div></div><div class="compare-row"><div><span>Grouped & optimised</span><strong>${num(t.km)} <small>km</small></strong></div><div class="bar green"><span style="width:${t.baseline?t.km/t.baseline*100:0}%"></span></div></div><div class="saving"><strong>↓ ${saving}%</strong><small>less estimated travel<br>for the same ${t.count} requests</small></div><p class="fine">Estimated load efficiency: <strong>${t.baseline?num(t.kg/t.baseline):'—'} → ${t.km?num(t.kg/t.km):'—'} kg/km</strong>.<br>Planning estimates only. Accepted weight is recorded after collection.</p><a href="#routes" class="btn full">Explore collection routes <span>↗</span></a></div>`;}
function table(requests,actions=false){if(!requests.length)return `<div class="empty"><h3>No collections here yet</h3><p>Book a pickup or change the filter to see requests.</p><a class="btn" href="#book">Book a pickup</a></div>`;return `<div class="table-wrap"><table><thead><tr><th>Request / material</th><th>Collection point</th><th>Est. weight</th><th>Status</th>${actions?'<th>Action</th>':''}</tr></thead><tbody>${requests.map(r=>`<tr><td>${material(r)}</td><td>${POINTS.find(p=>p.id===r.pointId)?.name}<small>${esc(r.id)} · ${esc(r.window)}</small></td><td>${num(r.estimated)} kg${r.recordedAt?`<small>${num(r.accepted)} kg accepted</small>`:''}</td><td>${status(r)}</td>${actions?`<td>${r.status==='scheduled'?`<button class="btn small" data-record="${esc(r.id)}">Record outcome</button>`:r.status==='pending'?'<a class="btn small" href="#routes">Plan round</a>':'<span class="fine">Recorded</span>'}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
const art=`<svg class="hero-art" viewBox="0 0 240 180" aria-hidden="true"><circle cx="133" cy="92" r="78" fill="none" stroke="#47715c" stroke-width="1"/><circle cx="133" cy="92" r="60" fill="none" stroke="#47715c" stroke-dasharray="3 5"/><path d="M33 132H211" stroke="#71926c"/><path d="M47 131V75L76 53 105 75V131" fill="#3b7357"/><path d="M41 76L76 48 111 76" stroke="#b9d295" stroke-width="3" fill="none"/><rect x="66" y="93" width="18" height="38" rx="3" fill="#8bb177"/><rect x="123" y="80" width="54" height="52" rx="6" fill="#dbeaab"/><path d="M119 80H181M138 75H160" stroke="#e8efce" stroke-width="6" stroke-linecap="round"/><text x="136" y="117" font-size="34" fill="#477849">↻</text><path d="M194 130V84M194 104Q174 102 179 82 198 85 194 104M194 91Q193 69 213 70 215 89 194 91" fill="#8daf72" stroke="#8daf72"/><circle cx="181" cy="36" r="19" fill="#497e5a"/><path d="M173 36l6 6 11-13" fill="none" stroke="#dcebaf" stroke-width="3"/><path d="M29 38q22-17 50-9m-6-8 8 8-10 5" stroke="#8eac7e" stroke-width="2" fill="none"/></svg>`;
function overview(){const groups=plan(state.requests);return heading('A little effort. A bigger loop.','Your neighbourhood’s recycling, brought together.','<a href="#book" class="btn primary">＋ Book a pickup</a>')+`<section class="hero"><div><p class="eyebrow">SMALL PICKUPS. SHARED PURPOSE.</p><h2>Good things happen<br>when we collect together.</h2><p>Turn scattered recycling requests into smarter rounds. Less travel. More material kept in the loop.</p><a href="#routes" class="btn lime">Plan the next round <span>↗</span></a></div>${art}</section>`+stats()+`<div class="split"><section class="card"><div class="card-head"><div><h2>Your neighbourhood, connected</h2><p>Meranti pilot · GreenLink collector (demo)</p></div><span class="badge">SYNTHETIC DATA</span></div>${map(groups)}</section><section class="card"><div class="card-head"><div><h2>A smarter way around</h2><p>Same requests. Fewer kilometres.</p></div><span>⌁</span></div>${comparison(groups)}</section></div><section class="card"><div class="card-head"><div><h2>Collection requests</h2><p>Every request is a step towards a fuller round.</p></div><a href="#collections" class="btn small">View all ↗</a></div>${table(state.requests.slice(-5).reverse())}</section>`;}
function booking(){return heading('Make room for a little good.','Choose your material. We’ll find it a place in the next round.','','RESIDENT · BOOK A PICKUP')+`<div class="status-steps"><span>01 Choose material</span><span>02 Pick a place & time</span><span>03 Join a collection round</span></div><div class="split"><form id="booking-form" class="card form-card"><h2>What are you recycling?</h2><p class="sub">One material per request. Add another booking for mixed loads.</p><div class="material-options">${Object.entries(MATERIALS).map(([id,m],i)=>`<label class="material-option"><input type="radio" name="material" value="${id}" ${i===0?'checked':''}><span>${m.icon}</span><strong>${m.name}</strong></label>`).join('')}</div><div class="fields"><label class="field">Approximate weight (kg)<input name="estimated" type="number" min="0.1" max="30" step="0.1" placeholder="e.g. 5" required><small class="fine">0.1–30 kg per booking</small></label><label class="field">Collection point<select name="pointId" required>${POINTS.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label class="field wide">Preferred pickup window<select name="window">${WINDOWS.map(w=>`<option>${w}</option>`).join('')}</select><small class="fine">All times MYT (UTC+8) · Fixed hackathon demo slots</small></label></div><div class="notice" id="preparation">${MATERIALS.paper.rule}</div><label class="checkbox"><input type="checkbox" name="prepared" required><span>I’ve checked the preparation guide. My material is clean, separated and accepted by GreenLink.</span></label><p class="error" id="booking-error" role="alert"></p><button class="btn primary full" type="submit">Request a pickup →</button><p class="fine">Demo only: no real collector is notified. No name, home address or phone number is needed.</p></form><aside class="card guide"><span class="badge">COLLECTOR ACCEPTANCE GUIDE</span><h2 style="margin-top:17px">A clean start makes a difference.</h2>${Object.values(MATERIALS).map(m=>`<div class="guide-item"><h3>${m.icon} ${m.name}</h3><p>${m.rule}</p></div>`).join('')}<div class="notice">Not accepted: glass, batteries, e-waste, food waste, plastic bags and contaminated materials. These cannot be booked in this pilot.</div><p class="fine">Demo acceptance rules. Confirm materials, preparation requirements and operating windows with a real collector before a field trial.</p></aside></div>`;}
function routes(){const groups=activePlans(),t=totals(groups);return heading('Fewer trips. Fuller rounds.','Compare the same requests, then assign a round to your collector.','','COLLECTOR · ROUTE PLANNER')+`<div class="toolbar" style="padding-left:0"><label for="window-filter" class="fine">Collection window</label><select id="window-filter" style="width:auto"><option value="all">All collection windows</option>${WINDOWS.map(w=>`<option ${selectedWindow===w?'selected':''}>${w}</option>`).join('')}</select><button class="btn small" id="route-mode">Show ${routeMode==='optimised'?'ungrouped':'optimised'} routes</button><span class="badge">${t.count} awaiting assignment</span></div><div class="split"><section class="card"><div class="card-head"><div><h2>${routeMode==='optimised'?'Grouped collection plan':'Individual pickup plan'}</h2><p>Hub → collection points → hub</p></div><span class="badge gray">SCHEMATIC</span></div>${map(groups,routeMode)}</section><section class="card"><div class="card-head"><h2>The same-request comparison</h2></div>${comparison(groups)}</section></div><section class="card"><div class="card-head"><div><h2>Suggested collection rounds</h2><p>GreenLink · accepts all 3 pilot materials · ${CAPACITY} kg estimated capacity per round</p></div></div>${groups.length?groups.map(g=>`<div class="round"><div class="round-top"><div><h3>${esc(g.window)}</h3><p class="sub">${g.stops.length} requests · ${new Set(g.stops.map(r=>r.pointId)).size} collection points</p></div><button class="btn primary small" data-dispatch="${g.index}">Assign round →</button></div><div class="stops"><span class="stop">⌂ Hub</span>${g.stops.map((r,i)=>`<span class="stop">${i+1}. ${POINTS.find(p=>p.id===r.pointId).name} · ${r.id}</span>`).join('')}<span class="stop">⌂ Hub</span></div><div class="numbers"><div><strong>${num(g.km)} <small>km</small></strong><small>Modelled route distance</small></div><div><strong>${num(g.estimated)} <small>kg</small></strong><small>Estimated collection load</small></div><div><strong>${num(g.estimated/g.km)} <small>kg/km</small></strong><small>Estimated load efficiency</small></div></div></div>`).join(''):'<div class="empty"><h3>All caught up.</h3><p>No unassigned requests for this window. Record assigned pickups in Collections.</p><a href="#collections" class="btn">Open collections</a></div>'}</section><details class="card method section-space"><summary>How the route comparison works</summary><p>Baseline: each eligible request gets its own hub-to-point-to-hub trip. Optimised: requests share a round within the same window, capped at ${CAPACITY} estimated kg. A nearest-neighbour route is refined with 2-opt; it is a heuristic, not a guarantee of the shortest possible route.</p><p>Both plans use exactly the same pending requests, collector, hub and distance model. Distances use a synthetic rectilinear grid (|Δx| + |Δy|), not road-network kilometres. No traffic, dwell time, vehicle volume, actual driven distance or emissions are inferred. Separate rounds in a window are assumed sequential; schedule feasibility requires collector validation.</p><p>The planned kg/km uses estimated booking weight. After all stops in a round are recorded, Impact shows accepted kg per modelled round kilometre. Neither measure proves material was recycled downstream.</p></details>`;}
function collections(){const requests=state.requests.filter(r=>collectionFilter==='all'||r.status===collectionFilter);return heading('Every pickup has a story.','Record what was actually accepted, rejected or missed.','<a href="#routes" class="btn primary">Plan a round ↗</a>','COLLECTOR · COLLECTIONS')+stats()+assignedRounds()+`<section class="card"><div class="card-head"><h2>Collection register</h2><span class="badge gray">${requests.length} REQUESTS</span></div><div class="toolbar"><label for="status-filter" class="fine">Status</label><select id="status-filter" style="width:auto">${['all','pending','scheduled','collected','rejected','missed'].map(v=>`<option value="${v}" ${v===collectionFilter?'selected':''}>${v==='all'?'All requests':v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select><span class="fine">Weights are recorded only after an assigned pickup.</span></div>${table(requests.slice().reverse(),true)}</section>`;}
function impact(){const m=metrics(state.requests),closed=state.requests.filter(r=>r.recordedAt);return heading('Impact you can trace.','Bookings are intentions. Accepted weights are collection evidence.','<button class="btn primary" id="export">↓ Export records</button>','SDP VIEW · IMPACT & RECORDS')+stats()+`<section class="card"><div class="impact-intro"><h2>Collection evidence, not a recycling claim.</h2><p class="sub" style="margin-top:9px">All figures here belong to this demo. “Accepted” means a collector-recorded collection outcome; downstream recycling has not been verified.</p></div><div class="card-head"><h2>Round performance</h2><span class="badge gray">${state.rounds.length} ASSIGNED</span></div>${state.rounds.length?`<div class="table-wrap"><table><thead><tr><th>Round / window</th><th>Outcomes</th><th>Modelled distance</th><th>Accepted weight</th><th>Accepted kg/km</th></tr></thead><tbody>${state.rounds.map(round=>{const rs=state.requests.filter(r=>r.roundId===round.id),rm=metrics(rs),done=rm.closed===rs.length;return `<tr><td>${round.id}<small>${esc(round.window)}</small></td><td>${rm.closed}/${rs.length} recorded<small>${done?'Round closed':'In progress'}</small></td><td>${num(round.km)} km</td><td>${num(rm.accepted)} kg</td><td>${done?num(rm.accepted/round.km):'—'}<small>${done?'Uses modelled distance':'Available when round closes'}</small></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty"><h3>The evidence starts with a collection.</h3><p>Assign a route, then record pickup outcomes to see round performance.</p><a class="btn" href="#routes">Plan a collection</a></div>'}</section><section class="card section-space"><div class="card-head"><div><h2>Traceable collection outcomes</h2><p>${closed.length} records · ${num(m.accepted)} kg accepted · ${num(m.rejected)} kg rejected</p></div></div>${closed.length?`<div class="table-wrap"><table><thead><tr><th>Request / source</th><th>Outcome</th><th>Accepted</th><th>Rejected</th><th>Reason / recorded time</th></tr></thead><tbody>${closed.map(r=>`<tr><td>${esc(r.id)}<small>${esc(r.source)}</small></td><td>${status(r)}</td><td>${num(r.accepted)} kg</td><td>${num(r.rejected)} kg</td><td class="record-note">${esc(r.reason||'No rejection')}<small>${new Date(r.recordedAt).toLocaleString('en-MY',{timeZone:'Asia/Kuala_Lumpur'})} MYT</small></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No outcomes recorded yet. Demo bookings never count as collected weight.</div>'}</section><div class="card method section-space"><h3>Measurement definitions</h3><p><strong>Completion rate:</strong> collected pickups ÷ closed pickups (collected + rejected + missed). Pending and scheduled requests are excluded. A partially accepted pickup counts as collected.<br><strong>Material rejection:</strong> rejected kg ÷ (accepted kg + rejected kg). Missed pickups have no inspected weight.<br><strong>Accepted kg/km:</strong> actual entered accepted weight ÷ the fixed modelled round distance, shown only after every stop is closed. No real-world distance saving is claimed.</p><p>Records are stored in this browser only, with no authentication or shared database. The resident, collector and SDP pages are demonstration views, not access-controlled roles. Validate the workflow with residents and a collector before deployment.</p></div>`;}
function render(){const page=location.hash.slice(1)||'overview';const pages={overview,book:booking,routes,collections,impact};const active=pages[page]?page:'overview';$('#app').innerHTML=(storageWarning?'<p class="notice">Browser storage is unavailable. Records may be lost on reload.</p>':'')+pages[active]();document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===active);if(a.dataset.page===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${{overview:'Overview',book:'Book a pickup',routes:'Route planner',collections:'Collections',impact:'Impact & records'}[active]}`;$('#pending-count').textContent=state.requests.filter(r=>r.status==='pending').length;bind();}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();$('#modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());}
function bind(){const form=$('#booking-form');if(form){form.onchange=()=>{$('#preparation').textContent=MATERIALS[new FormData(form).get('material')].rule;};form.onsubmit=e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(form));const booking=validateBooking({...data,prepared:!!data.prepared});const id='RL-'+String(Math.max(0,...state.requests.map(r=>Number(r.id.slice(3))))+1).padStart(3,'0');state.requests.push({...booking,id});save();$('#pending-count').textContent=state.requests.filter(r=>r.status==='pending').length;modal(`<div class="success-icon">✓</div><h2>Your request is in the loop.</h2><p class="sub" style="margin-top:12px">${id} · ${num(booking.estimated)} kg of ${MATERIALS[booking.material].name}</p><p>${POINTS.find(p=>p.id===booking.pointId).name}<br>${esc(booking.window)} MYT</p><div class="notice">Awaiting round assignment. This demo has not notified a collector.</div><div class="actions"><button class="btn" data-close>Book another</button><button class="btn primary" id="view-booking">View collections →</button></div>`);$('#view-booking').onclick=()=>{$('#modal').close();location.hash='collections';};form.reset();$('#preparation').textContent=MATERIALS.paper.rule;$('#booking-error').textContent='';}catch(err){$('#booking-error').textContent=err.message;}};}
if($('#window-filter'))$('#window-filter').onchange=e=>{selectedWindow=e.target.value;render();};if($('#route-mode'))$('#route-mode').onclick=()=>{routeMode=routeMode==='optimised'?'ungrouped':'optimised';render();};if($('#status-filter'))$('#status-filter').onchange=e=>{collectionFilter=e.target.value;render();};
document.querySelectorAll('[data-dispatch]').forEach(b=>b.onclick=()=>{const g=plan(state.requests).find(x=>x.index===Number(b.dataset.dispatch));if(!g)return;const id='ROUND-'+String(state.rounds.length+1).padStart(2,'0');state.rounds.push({id,window:g.window,km:g.km,baseline:g.baseline,requestIds:g.stops.map(r=>r.id),assignedAt:new Date().toISOString()});g.stops.forEach(r=>{r.status='scheduled';r.roundId=id;});save();render();toast(`${id} assigned to GreenLink. Record outcomes in Collections.`);});
document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>openOutcome(b.dataset.record));if($('#export'))$('#export').onclick=()=>{const blob=new Blob(['\ufeff'+csv(state.requests)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='reloop-demo-collection-records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo collection records exported.');};}
function openOutcome(id){const r=state.requests.find(r=>r.id===id);modal(`<div class="modal-title"><h2>Record collection outcome</h2><button class="close" data-close aria-label="Close">×</button></div><p class="sub" style="margin-top:12px">${r.id} · ${MATERIALS[r.material].name} · ${POINTS.find(p=>p.id===r.pointId).name}</p><form id="outcome-form"><div class="fields"><label class="field wide">Pickup outcome<select name="outcome"><option value="collected">Collected (all or partially accepted)</option><option value="rejected">Fully rejected</option><option value="missed">Missed pickup</option></select></label><label class="field">Actual accepted weight (kg)<input type="number" min="0" max="150" step="0.1" name="accepted" required placeholder="Weigh material"></label><label class="field">Rejected weight (kg)<input type="number" min="0" max="150" step="0.1" name="rejected" required value="0"></label><label class="field wide">Rejection / missed pickup reason<textarea name="reason" maxlength="200" placeholder="e.g. Food-contaminated cardboard"></textarea></label></div><div class="notice">Enter weighed quantities, not the booking estimate (${num(r.estimated)} kg). This is a demo collector record, not independent verification.</div><p class="error" id="outcome-error" role="alert"></p><div class="actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">Save outcome</button></div></form>`);$('#outcome-form [data-close]').onclick=()=>$('#modal').close();$('#outcome-form').onsubmit=e=>{e.preventDefault();try{const next=recordOutcome(r,Object.fromEntries(new FormData(e.target)));state.requests[state.requests.indexOf(r)]=next;save();$('#modal').close();render();toast('Outcome saved. Impact totals updated.');}catch(err){$('#outcome-error').textContent=err.message;}};}
$('#reset').onclick=()=>{modal('<div class="modal-title"><h2>Start a fresh demo?</h2><button class="close" data-close aria-label="Close">×</button></div><p>This replaces bookings, rounds and recorded outcomes in this browser with the original 12 synthetic requests. Export records first if you need them.</p><div class="actions"><button class="btn" data-close>Keep my records</button><button class="btn primary" id="confirm-reset">Reset demo</button></div>');$('#confirm-reset').onclick=()=>{state=seed();selectedWindow='all';collectionFilter='all';save();$('#modal').close();render();toast('Demo reset to 12 synthetic requests.');};};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});save();render();

function assignedRounds(){return state.rounds.length?`<section class="card section-space" style="margin-bottom:24px"><div class="card-head"><h2>Assigned routes · GreenLink</h2></div>${state.rounds.map(round=>`<details class="method"><summary>${round.id} · ${esc(round.window)} · ${num(round.km)} modelled km</summary><div class="stops"><span class="stop">⌂ Hub</span>${round.requestIds.map((id,i)=>{const r=state.requests.find(r=>r.id===id);return `<span class="stop">${i+1}. ${POINTS.find(p=>p.id===r.pointId).name} · ${id} · ${r.status}</span>`;}).join('')}<span class="stop">⌂ Hub</span></div></details>`).join('')}</section>`:'';}
